count_if.py.src:
votes = ["pear", "fig", "pear", "kiwi", "pear", "fig"]
counts = {}
for fruit in votes:
    if fruit in counts:
        counts[fruit] = counts[fruit] + 1
    else:
        counts[fruit] = 1
print(counts)

